// === Tab: Wake ===
class Wake {
	constructor(pos, r, ang, type) {
		this.ang = ang
		this.pos = pos;
		this.type = type;
		this.r = r;
		this.a = 220;
		this.sw = 1;
	}
	show() {
		push();
		translate(this.pos);
		rotate(this.ang);
		noFill();
		strokeWeight(this.sw);
		stroke(200, this.a);
		strokeCap(SQUARE);
		arc(-this.r, 0, this.r, this.r, -HALF_PI, HALF_PI); // main disturbance
		arc(-this.r, -this.r, this.r, this.r, HALF_PI, 3 * QUARTER_PI); // distortion wave
		arc(-this.r, this.r, this.r, this.r, 5 * QUARTER_PI, 3 * HALF_PI); // distortion wave
		fill(200, 200, 255, this.a);
		noStroke();
		ellipse(-this.r/2 - 20, 0, this.r / 10); // prop wake
		pop();
	}
	grow() {
		this.r += 0.5
		this.a -= 1;
		this.sw += 0.02;
	}
}

// === Tab: mySketch ===
// For the #WCCChallenge, theme: "waves".
// Lots of interesting info and pretty pictures here:
// https://en.wikipedia.org/wiki/Kelvin_wake_pattern

var pos, ang,tang, vel, lm, water;
var wakes = [];
var type = 0;

function setup() {
	createCanvas(windowWidth * 0.99, windowHeight * 0.99);
	water = createGraphics(width, height);
	pos = createVector(-width / 2, 0);
	lm = createVector(width / 2, 0);
	ang = PI;
	tang = PI;
	rectMode(CENTER);
	imageMode(CENTER);
	makeWater();
window.simulatedMouseX = width / 2;
}

function makeWater() {
	water.noFill();
	for (x = 0; x < water.width; x += 2) {
		for (y = 0; y < water.height; y += 2) {
			water.strokeWeight(2)
			water.stroke(0, 50, 128 + 128 * noise(x / 100, y / 100))
			water.point(x, y);
		}
	}
	water.filter(BLUR, 4);
}

function draw() {
	lm.lerp(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2), 0.1);
	ang = atan2(pos.y - lm.y, pos.x - lm.x) + (0.5 - noise(frameCount / 60)) / 2;
	vel = map(pos.dist(lm), height, 0, 2, 0);

	if (pos.dist(lm) > 15) {
		pos.x -= cos(ang) * 1.5;
		pos.y -= sin(ang) * 1.5;
		if (frameCount % 3 == 0 && pos.x < width) {
			wakes.push(new Wake(createVector(pos.x, pos.y), 15, PI + ang, type))
			type = 1 - type;
		}
	}
	blendMode(BLEND);
	background(0);
	push();
	translate(width / 2, height / 2)
	image(water, 0, 0);
	pop();
	translate(width / 2, height / 2);
	blendMode(ADD);
	for (w of wakes) {
		w.show();
		w.grow();
	}
	wakes = wakes.filter(w => w.a > 0);
	drawBoat();
}

function drawBoat() {
	push();
	blendMode(BLEND);
	translate(pos);
	rotate(PI + ang);
	noStroke();
	scale(0.8)
	arc(-10, 0, 50, 12, -7 * PI / 8, 7 * PI / 8, CHORD)
	fill(100);
	rect(-5, 0, 10, 10, 0, 4, 4, 0);
	pop();
}
